addEventListener('fetch',function(e){e.respondWith(handle(e.request));});
async function handle(r){
  var p=new URL(r.url).pathname;
  if(p==='/manifest.json')return new Response(getManifest(),{headers:{'Content-Type':'application/manifest+json','Cache-Control':'public,max-age=86400'}});
  if(p==='/apple-touch-icon.png'||p==='/apple-touch-icon-precomposed.png'){
    var b=atob(ICON_PNG);var u=new Uint8Array(b.length);
    for(var i=0;i<b.length;i++)u[i]=b.charCodeAt(i);
    return new Response(u,{headers:{'Content-Type':'image/png','Cache-Control':'public,max-age=86400'}});
  }
  if(p==='/icon.svg')return new Response(getIconSVG(),{headers:{'Content-Type':'image/svg+xml','Cache-Control':'public,max-age=86400'}});
  if(p==='/api/sync'){
    var code=(new URL(r.url)).searchParams.get('code')||'';
    if(!/^[A-Za-z0-9_-]{3,40}$/.test(code)){
      return new Response(JSON.stringify({error:'invalid code'}),{status:400,headers:{'Content-Type':'application/json'}});
    }
    var key='sync:'+code;
    if(r.method==='GET'){
      var v=await SYNC_KV.get(key);
      return new Response(v===null?'null':v,{headers:{'Content-Type':'application/json'}});
    }
    if(r.method==='POST'){
      var body=await r.text();
      if(body.length>1000000){
        return new Response(JSON.stringify({error:'too large'}),{status:413,headers:{'Content-Type':'application/json'}});
      }
      await SYNC_KV.put(key,body);
      return new Response(JSON.stringify({ok:true}),{headers:{'Content-Type':'application/json'}});
    }
    return new Response('Method Not Allowed',{status:405});
  }
  if(p==='/api/qlive'){
    var qcode=(new URL(r.url)).searchParams.get('code')||'';
    if(!/^[A-Za-z0-9_-]{3,40}$/.test(qcode)){
      return new Response(JSON.stringify({error:'invalid code'}),{status:400,headers:{'Content-Type':'application/json'}});
    }
    var qkey='qlive:'+qcode;
    if(r.method==='GET'){
      var qv=await SYNC_KV.get(qkey);
      return new Response(qv===null?'null':qv,{headers:{'Content-Type':'application/json'}});
    }
    if(r.method==='POST'){
      var qbody=await r.text();
      if(qbody.length>200000){
        return new Response(JSON.stringify({error:'too large'}),{status:413,headers:{'Content-Type':'application/json'}});
      }
      await SYNC_KV.put(qkey,qbody,{expirationTtl:3600});
      return new Response(JSON.stringify({ok:true}),{headers:{'Content-Type':'application/json'}});
    }
    return new Response('Method Not Allowed',{status:405});
  }
  return new Response(getHTML(),{headers:{'Content-Type':'text/html;charset=utf-8','Cache-Control':'no-store'}});
}
var ICON_PNG='';
