  '.now-card-lbl{font-size:11px;font-weight:700;color:var(--pk);letter-spacing:.08em;margin-bottom:3px;}',
  '.now-card-txt{font-size:13px;color:var(--tx);line-height:1.6;}',
  '.now-card-btn{flex-shrink:0;font-size:12px;font-weight:700;color:#fff;background:var(--pk);border-radius:12px;padding:8px 14px;white-space:nowrap;}',
  '.scen-sys-chips{display:flex;flex-wrap:wrap;gap:8px;justify-content:center;margin:14px 0 4px;}',
  '.scen-sys-chip{display:inline-flex;align-items:center;gap:5px;font-size:13px;font-weight:700;color:var(--tx);background:rgba(106,126,80,.1);border:1px solid var(--pl);border-radius:999px;padding:6px 12px;}',
  '.scen-sys-chip-ic{font-size:15px;}',
  '.scen-guide{background:rgba(90,120,160,.06);border:1px solid rgba(90,120,160,.18);border-radius:16px;padding:14px 16px;margin:16px 0;}',
  '.scen-guide-title{font-size:14px;font-weight:800;color:var(--tx);margin-bottom:12px;}',
  '.scen-step{display:flex;gap:11px;align-items:flex-start;margin-bottom:12px;}',
  '.scen-step:last-child{margin-bottom:0;}',
  '.scen-step-num{font-size:20px;flex-shrink:0;line-height:1.3;}',
  '.scen-step-txt{flex:1;min-width:0;}',
  '.scen-step-h{font-size:13.5px;font-weight:700;color:var(--tx);margin-bottom:2px;}',
  '.scen-step-d{font-size:12.5px;color:var(--tx2,#7a7367);line-height:1.6;}',
  '.scen-find{background:linear-gradient(135deg,rgba(106,126,80,.14),rgba(106,126,80,.04));border:1px solid var(--pl);border-radius:16px;padding:14px 16px;margin-bottom:16px;}',
  '.scen-find-lbl{font-size:13.5px;font-weight:800;color:var(--pk);margin-bottom:9px;}',
  '.scen-find-inp{width:100%;box-sizing:border-box;font-size:14px;padding:11px 13px;border:1.5px solid var(--pl);border-radius:12px;background:#fff;color:var(--tx);outline:none;}',
  '.scen-find-inp:focus{border-color:var(--pk);}',
  '.scen-find-res:not(:empty){margin-top:11px;}',
  '.scen-find-hint{font-size:12.5px;font-weight:700;color:var(--tx2,#7a7367);margin-bottom:8px;}',
  '.scen-find-empty{font-size:12.5px;color:var(--tx2,#7a7367);line-height:1.6;}',
  '.scen-suggest{background:#fff;border:1.5px solid var(--pk);border-radius:12px;padding:11px 13px;margin-bottom:8px;cursor:pointer;}',
  '.scen-suggest-top{display:flex;align-items:center;justify-content:space-between;gap:8px;}',
  '.scen-suggest-name{font-size:14px;font-weight:800;color:var(--tx);}',
  '.scen-suggest-sys{font-size:11.5px;font-weight:700;color:var(--pk);background:rgba(106,126,80,.12);border-radius:999px;padding:3px 9px;white-space:nowrap;}',
  '.scen-suggest-go{font-size:12px;font-weight:700;color:var(--pk);margin-top:6px;}',
  '.scen-grp-hdr{font-size:13px;font-weight:800;color:var(--pk);letter-spacing:.05em;margin:16px 0 8px;padding-bottom:5px;border-bottom:1px solid var(--pl);}',
  '.scen-driver{display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:rgba(90,120,160,.07);border-radius:10px;padding:8px 12px;margin-bottom:14px;}',
  '.scen-driver-lbl{font-size:11px;font-weight:800;color:var(--gr);letter-spacing:.04em;}',
  '.scen-driver-tx{font-size:13px;font-weight:700;color:var(--tx);}',
  '.scen-decode{border-left:3px solid var(--pl);}',
  '.scen-decode-drv{font-size:12.5px;font-weight:800;color:var(--pk);margin-bottom:6px;}',
  '.guidecard-cta{margin:4px 0 2px;background:linear-gradient(135deg,rgba(212,168,84,.16),rgba(212,168,84,.05));border:1px solid rgba(212,168,84,.4);border-radius:16px;padding:14px 16px;display:flex;align-items:center;gap:12px;cursor:pointer;}',
  '.guidecard-cta .gc-ic{font-size:26px;flex-shrink:0;}',
  '.guidecard-cta .gc-tx{flex:1;min-width:0;font-size:14px;font-weight:700;color:var(--tx);}',
  '.guidecard-cta .gc-tx small{display:block;font-size:12px;font-weight:500;color:var(--gr);margin-top:2px;}',
  '.guidecard-cta .gc-ar{font-size:18px;color:var(--wm);font-weight:800;}',
  '.guide-hero{text-align:center;padding:16px 8px 6px;}',
  '.guide-hero-ic{font-size:44px;}',
  '.guide-hero-t{font-size:18px;font-weight:800;color:var(--tx);margin-top:6px;}',
  '.guide-hero-s{font-size:13.5px;color:var(--gr);line-height:1.7;margin-top:8px;}',
  '.guide-sec{margin-top:22px;}',
  '.guide-sec-t{font-size:15px;font-weight:800;color:var(--pk);margin-bottom:12px;display:flex;align-items:center;gap:7px;}',
  '.guide-pillars{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;}',
  '.guide-pillar{background:#fff;border:1px solid #e8eee0;border-radius:14px;padding:12px 4px;text-align:center;cursor:pointer;transition:transform .1s;}',
  '.guide-pillar:active{transform:scale(.95);}',
  '.guide-pillar-ic{font-size:24px;}',
  '.guide-pillar-lb{font-size:13px;font-weight:800;color:var(--tx);margin-top:4px;}',
  '.guide-feat{background:#fff;border:1px solid #e8eee0;border-radius:16px;padding:13px 14px;margin-bottom:10px;display:flex;align-items:flex-start;gap:12px;cursor:pointer;transition:transform .1s;}',
  '.guide-feat:active{transform:scale(.98);}',
  '.guide-feat-ic{font-size:26px;flex-shrink:0;line-height:1.2;}',
  '.guide-feat-info{flex:1;min-width:0;}',
  '.guide-feat-name{font-size:14.5px;font-weight:800;color:var(--tx);}',
  '.guide-feat-desc{font-size:12.5px;color:var(--gr);line-height:1.65;margin-top:3px;}',
  '.guide-feat-go{font-size:20px;color:var(--pl);font-weight:800;flex-shrink:0;align-self:center;}',
  '.guide-gest{display:flex;gap:12px;align-items:flex-start;background:rgba(90,120,160,.06);border-radius:12px;padding:11px 13px;margin-bottom:8px;}',
  '.guide-gest-ic{font-size:22px;flex-shrink:0;}',
  '.guide-gest-tx{flex:1;min-width:0;}',
  '.guide-gest-h{font-size:13.5px;font-weight:700;color:var(--tx);}',
  '.guide-gest-d{font-size:12.5px;color:var(--gr);line-height:1.6;margin-top:2px;}',
  '.guide-flow{background:linear-gradient(135deg,rgba(106,126,80,.12),rgba(106,126,80,.03));border:1px solid var(--pl);border-radius:16px;padding:16px 14px;}',
  '.guide-flow-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:center;}',
  '.guide-flow-node{font-size:13px;font-weight:800;color:var(--pk);background:#fff;border:1.5px solid var(--pl);border-radius:999px;padding:7px 13px;}',
  '.guide-flow-arw{font-size:15px;color:var(--pl);font-weight:800;}',
  '.guide-flow-cap{font-size:12.5px;color:var(--gr);line-height:1.7;text-align:center;margin-top:12px;}',
  '.ba-q{font-size:16px;font-weight:800;color:var(--tx);margin:6px 0 4px;}',
  '.ba-qs{font-size:13px;color:var(--gr);line-height:1.6;margin-bottom:14px;}',
  '.ba-input{width:100%;box-sizing:border-box;font-size:15px;padding:12px 14px;border:1.5px solid var(--pl);border-radius:12px;background:#fff;color:var(--tx);outline:none;margin-bottom:16px;}',
  '.ba-input:focus{border-color:var(--pk);}',
  '.ba-chips{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px;}',
  '.ba-chip{font-size:13.5px;font-weight:600;color:var(--tx);background:#fff;border:1.5px solid var(--pl);border-radius:999px;padding:9px 14px;cursor:pointer;transition:all .12s;}',
  '.ba-chip.sel{background:var(--pk);border-color:var(--pk);color:#fff;}',
  '.ba-clbl{font-size:13.5px;font-weight:800;color:var(--pk);margin-bottom:9px;}',
  '.ba-type-card{background:linear-gradient(135deg,rgba(106,126,80,.16),rgba(106,126,80,.04));border:1.5px solid var(--pk);border-radius:18px;padding:18px 16px;text-align:center;margin-bottom:16px;}',
  '.ba-type-ic{font-size:40px;}',
  '.ba-type-name{font-size:19px;font-weight:800;color:var(--pk);margin-top:6px;}',
  '.ba-type-feat{font-size:13px;font-weight:700;color:var(--tx);margin-top:6px;}',
  '.ba-type-body{font-size:13px;color:var(--gr);line-height:1.75;margin-top:10px;text-align:left;}',
  '.ba-rev-head{font-size:14.5px;font-weight:800;color:var(--tx);line-height:1.7;background:rgba(212,168,84,.14);border-left:3px solid var(--wm);border-radius:10px;padding:12px 14px;margin-bottom:14px;}',
  '.ba-rev-row{display:flex;gap:11px;align-items:flex-start;background:#fff;border:1px solid #e8eee0;border-radius:12px;padding:11px 13px;margin-bottom:8px;cursor:pointer;}',
  '.ba-rev-ic{font-size:22px;flex-shrink:0;}',
  '.ba-rev-tx{flex:1;min-width:0;}',
  '.ba-rev-h{font-size:13px;font-weight:800;color:var(--pk);}',
  '.ba-rev-d{font-size:12.5px;color:var(--tx);line-height:1.65;margin-top:2px;}',
  '.ba-rev-go{font-size:16px;color:var(--pl);font-weight:800;flex-shrink:0;align-self:center;}',
  '.share-toast.show{opacity:1;}',
  '</style>',
