  'function qstArtSVG(catKey,objKey,photoIdx){',
  '  if(catKey==="O"){return (typeof QST_OBJ_PHOTOS!=="undefined"&&QST_OBJ_PHOTOS[objKey])?\'<img src="data:image/jpeg;base64,\'+QST_OBJ_PHOTOS[objKey]+\'" alt="">\':"";}',
  '  if(QST_PHOTOS[catKey]){',
  '    var photoPool=QST_PHOTOS[catKey];',
  '    var photo=photoPool[(photoIdx||0)%photoPool.length];',
  '    return \'<img src="data:image/jpeg;base64,\'+photo+\'" alt="">\';',
  '  }',
  '  return "";',
  '}',
  'var QST_CARDS=[',
